203	    public List<Pet> getPets() {
204	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
205	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
206	        return Collections.unmodifiableList(sortedPets);
