223	     */
224	    public Pet getPet(String name) {
225	        return getPet(name, false);
226	    }
227	
228	    /**
229	     * Return the Pet with the given name, or null if none found for this Owner.
230	     *
231	     * @param name to test
232	     * @return true if pet name is already in use
233	     */
234	    public Pet getPet(String name, boolean ignoreNew) {
235	        name = name.toLowerCase();
236	        for (Pet pet : getPetsInternal()) {
237	            if (!ignoreNew || !pet.isNew()) {
238	                String compName = pet.getName();
239	                compName = compName.toLowerCase();
240	                if (compName.equals(name)) {
241	                    return pet;
242	                }
243	            }
244	        }
245	        return null;
246	    }
247	
248	    public Pet getPet(Integer petId) {
249	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
250	    }
251	
252	    @Override
253	    public String toString() {
254	        return new ToStringCreator(this)
255	
256	            .append("id", this.getId())
257	            .append("new", this.isNew())
258	            .append("lastName", this.getLastName())
259	            .append("firstName", this.getFirstName())
260	            .append("address", this.address)
261	            .append("city", this.city)
262	            .append("telephone", this.telephone)
263	            .append("email", this.email)
264	            .toString();
265	    }
266	}
