1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials",
24	        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" "
25	            + "+ Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
26	    @Mapping(target = "membershipLevel",
27	        expression = "java(Math.min(3, 1 "
28	            + "+ ((owner.getEmail() != null && !owner.getEmail().isBlank()) ? 1 : 0) "
29	            + "+ ((owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) ? 1 : 0)))")
30	    @Mapping(target = "locality",
31	        expression = "java(org.springframework.samples.petclinic.util.LocalityResolver.resolve(owner.getCity(), owner.getPostcode()))")
32	    @Mapping(target = "contactPreference",
33	        expression = "java((owner.getEmail() != null && !owner.getEmail().isBlank()) "
34	            + "? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE)")
35	    @Mapping(target = "checkDigit",
36	        expression = "java(owner.getCustomerCode() == null ? null "
37	            + ": org.springframework.samples.petclinic.util.LuhnCheckDigit.compute(owner.getCustomerCode()))")
38	    OwnerDto toOwnerDto(Owner owner);
39	
40	    Owner toOwner(OwnerDto ownerDto);
41	
42	    @Mapping(target = "id", ignore = true)
43	    @Mapping(target = "pets", ignore = true)
44	    Owner toOwner(OwnerFieldsDto ownerDto);
45	
46	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
47	
48	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
49	
50	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
51	        OwnerPageDto ownerPageDto = new OwnerPageDto();
52	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
53	        ownerPageDto.setPage(ownerPage.getNumber());
54	        ownerPageDto.setSize(ownerPage.getSize());
55	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
56	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
57	        return ownerPageDto;
58	    }
59	}
