17	package org.springframework.samples.petclinic.util;
18	
19	/**
20	 * Computes the Luhn check digit over the decimal digits contained in a string. Non-digit
21	 * characters are ignored, so the check digit is taken over the digits of an owner's customer code
22	 * (e.g. {@code "SMI-0007"} contributes the digits {@code 0007}).
23	 */
24	public final class LuhnCheckDigit {
25	
26	    private LuhnCheckDigit() {
27	    }
28	
29	    /**
30	     * Returns the Luhn check digit (0-9) over the decimal digits contained in {@code s}. Starting
31	     * from the right-most digit, every second digit is doubled (subtracting 9 when the result
32	     * exceeds 9) before being summed; the check digit is the amount needed to bring the running
33	     * total to the next multiple of ten.
34	     *
35	     * @param s the source string whose digits are used (must not be {@code null})
36	     * @return the Luhn check digit, a single value from 0 to 9
37	     */
38	    public static int compute(String s) {
39	        int sum = 0;
40	        boolean dbl = true;
41	        for (int i = s.length() - 1; i >= 0; i--) {
42	            char c = s.charAt(i);
43	            if (c < '0' || c > '9') {
44	                continue;
45	            }
46	            int d = c - '0';
47	            if (dbl) {
48	                d *= 2;
49	                if (d > 9) {
50	                    d -= 9;
51	                }
52	            }
53	            sum += d;
54	            dbl = !dbl;
55	        }
56	        return (10 - (sum % 10)) % 10;
57	    }
58	}
