17	package org.springframework.samples.petclinic.util;
18	
19	import java.util.Map;
20	
21	/**
22	 * Derives an owner's 'locality' (canonical region). The postcode is preferred: the region is
23	 * looked up by postcode range first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), and only when
24	 * the postcode is absent or in no known range does it fall back to a fixed city-to-region table.
25	 * This returns the same region for known cities but disambiguates cities that share a name. Any
26	 * input that resolves to neither derives the region {@code "UNKNOWN"}.
27	 */
28	public final class LocalityResolver {
29	
30	    /** Fixed city-to-region table; anything not listed derives locality "UNKNOWN". */
31	    private static final Map<String, String> CITY_REGION = Map.of(
32	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
33	
34	    /** Region -> inclusive 4-digit postcode range {low, high}. */
35	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
36	        "NSW", new int[] {2000, 2099},
37	        "VIC", new int[] {3000, 3099},
38	        "QLD", new int[] {4000, 4099});
39	
40	    private LocalityResolver() {
41	    }
42	
43	    /**
44	     * Returns the canonical region for the given owner, preferring the postcode. The postcode is
45	     * matched against the known region ranges first; when it is {@code null} or in no known range,
46	     * the region is derived from the city via {@link #resolve(String)}.
47	     *
48	     * @param city     the owner's city (may be {@code null})
49	     * @param postcode the owner's postcode (may be {@code null})
50	     * @return the canonical region string, or {@code "UNKNOWN"}
51	     */
52	    public static String resolve(String city, String postcode) {
53	        String byPostcode = fromPostcode(postcode);
54	        return byPostcode != null ? byPostcode : resolve(city);
55	    }
56	
57	    /**
58	     * Returns the canonical region for the given city, or {@code "UNKNOWN"} when the city is
59	     * {@code null} or not present in the fixed city-to-region table.
60	     *
61	     * @param city the owner's city (may be {@code null})
62	     * @return the canonical region string, or {@code "UNKNOWN"}
63	     */
64	    public static String resolve(String city) {
65	        return city == null ? "UNKNOWN" : CITY_REGION.getOrDefault(city, "UNKNOWN");
66	    }
67	
68	    /**
69	     * Returns the region whose range contains the postcode, or {@code null} when the postcode is
70	     * {@code null}, not a parseable integer, or in no known range.
71	     */
72	    private static String fromPostcode(String postcode) {
73	        if (postcode == null) {
74	            return null;
75	        }
76	        int value;
77	        try {
78	            value = Integer.parseInt(postcode.trim());
79	        }
80	        catch (NumberFormatException e) {
81	            return null;
82	        }
83	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
84	            int[] range = entry.getValue();
85	            if (value >= range[0] && value <= range[1]) {
86	                return entry.getKey();
87	            }
88	        }
89	        return null;
90	    }
91	}
