268	     * owner's adjusted business-day registration date, with 429 Too Many Requests.
269	     *
270	     * @param owner the owner being created
271	     */
272	    private void rejectWhenDailyLimitReached(Owner owner) {
273	        if (countOwnersRegisteredOn(owner.getRegistrationDate()) >= MAX_OWNERS_PER_DAY) {
274	            throw new DailyOwnerLimitExceededException(
275	                "The maximum number of owners that may be created today has already been reached");
276	        }
