460	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
461	        if (currentOwner == null) {
462	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
463	        }
464	        currentOwner.setAddress(ownerFieldsDto.getAddress());
465	        currentOwner.setCity(ownerFieldsDto.getCity());
466	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
467	        currentOwner.setLastName(ownerFieldsDto.getLastName());
468	        // Normalize the telephone to canonical E.164 form so it is stored and returned
469	        // consistently with create; an unformattable value is rejected with 400.
470	        currentOwner.setTelephone(telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
471	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
472	        this.clinicService.saveOwner(currentOwner);
473	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
